      crBtn.style.cssText = 'border-color:rgba(61,170,110,0.4);color:#4CAF82;background:rgba(61,170,110,0.08);margin-left:4px;';
      crBtn.onclick = function() { self.openPopup(); };
      row.appendChild(crBtn);
